import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper";
import "swiper/css";
import axios from "axios";

// Components
import CategoryCard from "../CategoryCard/CategoryCard";
import DisplayedProduct from "./DisplayedProduct";

/**
 * CategorySwiper - Isolated memoized component for the category slider.
 * This prevents the entire Swiper complex from re-rendering when the parent
 * state (productShown) changes on hover.
 */
const CategorySwiper = React.memo(({ category, onSetProductShown, slidesPerView }) => {
  return (
    <Swiper
      className="rounded-lg pb-0"
      slidesPerView={slidesPerView}
      spaceBetween={20}
      autoplay={{
        delay: 3500,
        disableOnInteraction: true,
        pauseOnMouseEnter: true,
      }}
      loop={true}
      modules={[Autoplay]}
    >
      {category.map((item, index) => {
        if (index % 2 === 0) {
          let img = "";
          try {
            const imgPath = item.products[0][1];
            img = imgPath ? ((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + imgPath) : "";
          } catch {
            img = "";
          }
          let img1 = "";
          try {
            const imgPath1 = category[index + 1]?.products[0][1];
            img1 = imgPath1 ? ((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + imgPath1) : "";
          } catch {
            img1 = "";
          }

          return (
            <SwiperSlide key={index}>
              {/* Category card 1 */}
              <CategoryCard
                key={`cat-${index}`}
                index={index}
                link={item.categoryLink}
                title={item.categoryName}
                description={item.discription}
                img={img}
                rating={item.products[0][5]}
                stars={item.products[0][4]}
                setProductShown={onSetProductShown}
              />
              
              {/* Category card 2 (if exists) */}
              {category[index + 1] && (
                <CategoryCard
                  key={`cat-${index + 1}`}
                  index={index + 1}
                  link={category[index + 1].categoryLink}
                  title={category[index + 1].categoryName}
                  description={category[index + 1].discription}
                  img={img1}
                  rating={category[index + 1].products[0][5]}
                  stars={category[index + 1].products[0][4]}
                  setProductShown={onSetProductShown}
                />
              )}
            </SwiperSlide>
          );
        }
        return null;
      })}
    </Swiper>
  );
});

const MainProducts = () => {
  const [productShown, setProductShown] = useState(-1);
  const [category, setCategory] = useState([]);

  useEffect(() => {
    axios
      .get((process.env.REACT_APP_SERVER || "").replace(/\/$/, "") + "/api/homeCategoryList/")
      .then((data) => {
        const fetchedCategories = data["data"]["data"];
        setCategory(fetchedCategories);
        if (fetchedCategories.length > 0) {
          setProductShown(0);
        }
      })
      .catch((error) => console.log(error));
  }, []);

  // Debounced hover handler to avoid frame drops during rapid movement
  const hoverTimeoutRef = React.useRef(null);
  const handleSetProductShown = useCallback((index) => {
    if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
    hoverTimeoutRef.current = setTimeout(() => {
      setProductShown(index);
    }, 150); // Debounce delay prevents triggering rapid state updates/re-renders during scroll
  }, []);

  const slidesPerView = useMemo(() => (window.innerWidth > 640 ? 4 : 2), []);

  return (
    <>
      <div className="box h-[5rem] w-[25rem] relative flex justify-start items-start ml-[2rem] group mt-6">
        <div className="h-12 w-1.5 bg-[#004B95] absolute mr-[1rem] origin-left group-hover:w-[16rem] duration-300 group"></div>
        <h2 className="text-[24px] absolute font-bold text-[#004B95] mt-[0.5rem] ml-[1rem] group-hover:text-white group-hover:translate-x-5 duration-300">
          Our Products
        </h2>
      </div>
      <div className="flex p-[10px] gap-[15px] max-w-full" id="ourProducts">
        <DisplayedProduct
          productShown={productShown}
          data={category[productShown]}
        />
        {category.length > 0 && (
          <CategorySwiper 
            category={category} 
            onSetProductShown={handleSetProductShown} 
            slidesPerView={slidesPerView}
          />
        )}
      </div>
    </>
  );
};

export default MainProducts;
